-- Tags: no-fasttest
-- no-fasttest: requires the ORC input format, which is not built in fasttest.

-- A nested ORC union (a union branch that is itself a union) would map to a Variant nested inside a
-- Variant, which the Variant type forbids. It must be reported as an unsupported ORC type (and be
-- skippable), not fail with a confusing BAD_ARGUMENTS from the Variant constructor.

SET allow_experimental_variant_type = 1;

-- uniontype<uniontype<int, string>, double>: schema inference rejects the nested union.
DESC format(ORC, unhex('')); -- { serverError CANNOT_EXTRACT_TABLE_STRUCTURE }
SELECT * FROM format(ORC, unhex('')) FORMAT Null; -- { serverError CANNOT_EXTRACT_TABLE_STRUCTURE }

-- The nested-union column is skipped and the remaining supported columns are still read (here a
-- plain Int32 'id'), instead of failing the whole file.
SELECT * FROM format(ORC, unhex('')) ORDER BY id SETTINGS input_format_orc_skip_columns_with_unsupported_types_in_schema_inference = 1 FORMAT TSVWithNames;

-- With an explicit structure the data-read path also rejects the nested union cleanly.
SELECT * FROM format(ORC, 'u Variant(Int32, String, Float64)', unhex('')) FORMAT Null SETTINGS allow_suspicious_variant_types = 1; -- { serverError UNKNOWN_TYPE }
